    u"// \uc2ac\ub7ec\uadf8\ub85c \uc9c0\uc5ed \ub370\uc774\ud130 \ucc3e\uae30\n"
    u"export function getRegionPayData(regionSlug: string): RegionPayData | undefined {\n"
    u"    return REGION_PAY_DATA.find(r =>\n"
    u"        r.slugs.some(s => s === regionSlug || regionSlug.includes(s) || s.includes(regionSlug))\n"
    u"    );\n"
    u"}\n\n"
    u"// \uc5c5\uc885 \uc2ac\ub7ec\uadf8 \uac80\uc99d - '\uc54c\ubc14' \uc811\ubbf8\uc0ac\uac00 \ubd99\uc740 \uacbd\uc6b0\ub3c4 \uc720\uc5f0\ud558\uac8c \ub300\uc751\n"
    u"export function isWorkTypeSlug(slug: string): slug is WorkTypeSlug {\n"
    u"    // \ub8ec\uc54c\ubc14, \uc9ec\uc624\uc54c\ubc14 \ub4f1 '\uc54c\ubc14'\uc790\uccb4\uac00 \ud3ec\ud568\ub41c \uc5c5\uc885\uba85 \uc608\uc678 \ucc34\ub9ac \uc704\ud568\n"
    u"    if (WORK_TYPE_SLUGS.includes(slug as WorkTypeSlug)) return true;\n"
    u"    const cleanSlug = slug.endsWith('\uc54c\ubc14') ? slug.replace('\uc54c\ubc14', '') : slug;\n"
    u"    return WORK_TYPE_SLUGS.includes(cleanSlug as WorkTypeSlug);\n"
    u"}\n\n"
    u"// \uc694\uccad\ub41c \uc2ac\ub7ec\uadf8\uc5d0 \ub300\uc751\ud558\ub294 \uc2e4\uc81c \ub370\uc774\ud130 \ud0a4 \ubc18\ud658\n"
    u"export function getNormalizedWorkTypeSlug(slug: string): WorkTypeSlug | undefined {\n"
    u"    if (WORK_TYPE_SLUGS.includes(slug as WorkTypeSlug)) return slug as WorkTypeSlug;\n"
    u"    const cleanSlug = slug.endsWith('\uc54c\ubc14') ? slug.replace('\uc54c\ubc14', '') : slug;\n"
    u"    if (WORK_TYPE_SLUGS.includes(cleanSlug as WorkTypeSlug)) {\n"
    u"        return cleanSlug as WorkTypeSlug;\n"
    u"    }\n"
    u"    return undefined;\n"
    u"}\n"
